css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .pole { position: absolute; left: 24%; top: 8%; width: calc(var(--loader-size) * .04); height: 84%; background: linear-gradient(#cbd5e1, #64748b); border-radius: 3px; }
.loader .flag { position: absolute; left: 26%; top: 12%; width: 50%; height: 32%; background: linear-gradient(135deg, var(--accent), var(--accent-2)); border-radius: 0 4px 4px 0; transform-origin: left center; animation: wave calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
@keyframes wave { 0%, 100% { transform: rotate(-1.5deg) skewY(4deg); border-radius: 0 4px 30% 4px; } 25% { transform: rotate(1.5deg) skewY(-5deg); border-radius: 0 4px 4px 30%; } 50% { transform: rotate(-1.5deg) skewY(4deg); border-radius: 0 30% 4px 4px; } 75% { transform: rotate(1deg) skewY(-3deg); } }
